+#include <QStandardPaths>
+
+#include <chrono>
+
+using namespace std::chrono_literals;
+using namespace Qt::StringLiterals;
 using namespace NotificationManager;

+static QString historyFilePath()
+{
+    return QStandardPaths::writableLocation(QStandardPaths::GenericStateLocation) + u"/plasmanotificationhistory.json"_s;
+}
+
 NotificationsModel::Ptr NotificationsModel::createNotificationsModel()
 {
     static std::weak_ptr<NotificationsModel> s_instance;
@@ -45,6 +65,165 @@ NotificationsModel::NotificationsModel()
         }
     });
     Server::self().init();
+
+    // Only the owner of the notification service keeps the history across restarts
+    if (!Server::self().isValid()) {
+        return;
+    }
+
+    loadHistory();
+
+    m_saveHistoryTimer.setSingleShot(true);
+    m_saveHistoryTimer.setInterval(2s);
+    connect(&m_saveHistoryTimer, &QTimer::timeout, this, &NotificationsModel::saveHistory);
+
+    auto scheduleSaveHistory = [this] {
+        if (!m_saveHistoryTimer.isActive()) {
+            m_saveHistoryTimer.start();
+        }
+    };
+    connect(this, &QAbstractItemModel::rowsInserted, this, scheduleSaveHistory);
+    connect(this, &QAbstractItemModel::rowsRemoved, this, scheduleSaveHistory);
+    connect(this, &QAbstractItemModel::dataChanged, this, scheduleSaveHistory);
+    connect(this, &AbstractNotificationsModel::lastReadChanged, this, scheduleSaveHistory);
+    connect(QCoreApplication::instance(), &QCoreApplication::aboutToQuit, this, [this] {
+        if (m_saveHistoryTimer.isActive()) {
+            saveHistory();
+        }
+    });
+}
+
+NotificationsModel::~NotificationsModel()
+{
+    if (m_saveHistoryTimer.isActive()) {
+        saveHistory();
+    }
+}
+
+void NotificationsModel::loadHistory()
+{
+    QFile file(historyFilePath());
+    if (!file.open(QIODevice::ReadOnly)) {
+        return;
+    }
+
+    const QJsonObject history = QJsonDocument::fromJson(file.readAll()).object();
+
+    const QDateTime lastRead = QDateTime::fromString(history.value(u"lastRead"_s).toString(), Qt::ISODateWithMs);
+    if (lastRead.isValid()) {
+        setLastRead(lastRead);
+    }
+
+    uint highestId = 0;
+
+    const QJsonArray notificationsArray = history.value(u"notifications"_s).toArray();
+    for (const QJsonValue &value : notificationsArray) {
+        const QJsonObject object = value.toObject();
+
+        const uint id = object.value(u"id"_s).toInteger();
+        if (id == 0 || rowOfNotification(id) > -1) {
+            continue;
+        }
+
+        Notification notification(id);
+        notification.setSummary(object.value(u"summary"_s).toString());
+        notification.setBody(object.value(u"body"_s).toString());
+        notification.setApplicationName(object.value(u"applicationName"_s).toString());
+        notification.processHints(object.value(u"hints"_s).toObject().toVariantMap());
+
+        const QString desktopEntry = object.value(u"desktopEntry"_s).toString();
+        if (!desktopEntry.isEmpty() && desktopEntry != notification.desktopEntry()) {
+            notification.setDesktopEntry(desktopEntry);
+        }
+        notification.setApplicationName(object.value(u"applicationName"_s).toString());
+        notification.setApplicationIconName(object.value(u"applicationIconName"_s).toString());
+
+        const QString icon = object.value(u"icon"_s).toString();
+        if (!icon.isEmpty() && notification.image().isNull()) {
+            notification.setIcon(icon);
+        }
+
+        notification.setCreated(QDateTime::fromString(object.value(u"created"_s).toString(), Qt::ISODateWithMs));
+        notification.d->updated = QDateTime::fromString(object.value(u"updated"_s).toString(), Qt::ISODateWithMs);
+        notification.setRead(object.value(u"read"_s).toBool());
+        notification.setWasAddedDuringInhibition(object.value(u"wasAddedDuringInhibition"_s).toBool());
+
+        // The application that sent it no longer knows about it, so it is just an entry in the history now
+        notification.setResident(false);
+        notification.setTimeout(0);
+        notification.setExpired(true);
+
+        onNotificationAdded(notification);
+        highestId = std::max(highestId, id);
+    }
+
+    // Don't hand out the IDs of the restored notifications again
+    uint &nextId = Server::self().d->m_highestNotificationId;
+    nextId = std::max(nextId, highestId + 1);
+}
+
+void NotificationsModel::saveHistory()
+{
+    m_saveHistoryTimer.stop();
+
+    if (!Server::self().isValid()) {
+        return;
+    }
+
+    QJsonArray notificationsArray;
+    for (const Notification &notification : notifications()) {
+        // As per spec, transient notifications bypass the server's persistence capability
+        if (notification.transient()) {
+            continue;
+        }
+
+        QJsonObject hints;
+        const QVariantMap notificationHints = notification.hints();
+        for (auto it = notificationHints.cbegin(); it != notificationHints.cend(); ++it) {
+            QVariant value = it.value();
+            // D-Bus bytes, like the urgency, would be written as characters
+            if (value.typeId() == QMetaType::UChar) {
+                value = value.toInt();
+            }
+            const QJsonValue hint = QJsonValue::fromVariant(value);
+            if (!hint.isNull() && !hint.isUndefined()) {
+                hints.insert(it.key(), hint);
+            }
+        }
+
+        notificationsArray.append(QJsonObject{
+            {u"id"_s, static_cast<qint64>(notification.id())},
+            {u"created"_s, notification.created().toString(Qt::ISODateWithMs)},
+            {u"updated"_s, notification.updated().toString(Qt::ISODateWithMs)},
+            {u"summary"_s, notification.summary()},
+            {u"body"_s, notification.rawBody()},
+            {u"icon"_s, notification.icon()},
+            {u"applicationName"_s, notification.applicationName()},
+            {u"applicationIconName"_s, notification.applicationIconName()},
+            {u"desktopEntry"_s, notification.desktopEntry()},
+            {u"read"_s, notification.read()},
+            {u"wasAddedDuringInhibition"_s, notification.wasAddedDuringInhibition()},
+            {u"hints"_s, hints},
+        });
+    }
+
+    const QJsonObject history{
+        {u"lastRead"_s, lastRead().toString(Qt::ISODateWithMs)},
+        {u"notifications"_s, notificationsArray},
+    };
+
+    const QString path = historyFilePath();
+    QDir().mkpath(QFileInfo(path).absolutePath());
+
+    QSaveFile file(path);
+    if (!file.open(QIODevice::WriteOnly)) {
+        qCWarning(NOTIFICATIONMANAGER) << "Failed to save the notification history to" << path << file.errorString();
+        return;
+    }
+    file.write(QJsonDocument(history).toJson(QJsonDocument::Compact));
+    if (!file.commit()) {
+        qCWarning(NOTIFICATIONMANAGER) << "Failed to save the notification history to" << path << file.errorString();
+    }
 }

 void NotificationsModel::expire(uint notificationId)
